class Solution {
  public int minSwaps(int[] nums) {
    int n = nums.length, evens = 0;
    int[] pos = new int[n];
    for (int i = 0; i < n; i++) if (nums[i] % 2 == 0) pos[evens++] = i;
    int odds = n - evens;
    if (Math.abs(evens - odds) > 1) return -1;
    long best = Long.MAX_VALUE;
    for (int startSlot = 0; startSlot < 2; startSlot++) {
      // evens occupy slots startSlot, startSlot + 2, ...
      int slots = (n - startSlot + 1) / 2;
      if (slots != evens) continue;
      long cost = 0;
      for (int k = 0; k < evens; k++) cost += Math.abs(pos[k] - (startSlot + 2 * k));
      best = Math.min(best, cost);
    }
    return (int) best;
  }
}
